/**
 * toml -> tomli (Python).
 *
 * Why this pair: `toml` is unmaintained and tomli is its recommended successor (it became the
 * standard library's tomllib). The séance generates TOML documents from a model and compares both
 * parsers; it also damages documents at random and checks that nothing the old parser accepts is
 * rejected by the new one. Python on the scratch host is 3.9, so tomllib is not available and tomli
 * is the target.
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { callsNote, pyProjectCalls } from '../examples.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { depOfContext, oldVersionsFor } from '../versions.js';

const DIR = 'seance/toml';

export const TOML_KNOWN: KnownDifference[] = [
  {
    input: 'toml.loads("a = [1, \\"x\\"]")',
    old: 'raises TomlDecodeError (mixed-type arrays are rejected)',
    naive: '{"a": [1, "x"]}',
    handled: 'Accepted: mixed arrays are valid TOML 1.0 and tomli reads them.',
  },
  {
    input: 'toml.loads("a = \\"\\\\x41\\"")',
    old: 'raises TomlDecodeError (no \\x escape)',
    naive: '{"a": "A"}',
    handled: 'Accepted: tomli reads the \\x escape.',
  },
  {
    input: 'except toml.TomlDecodeError',
    old: 'class TomlDecodeError',
    naive: 'class tomli.TOMLDecodeError (different name and capitalisation)',
    handled:
      'Reproduced: toml_replacement.TomlDecodeError is tomli.TOMLDecodeError, so the old except clause still works.',
  },
  {
    input: 'toml.loads(s, _dict=OrderedDict)',
    old: 'returns OrderedDict tables',
    naive: 'TypeError: unexpected keyword argument _dict',
    handled: 'Reproduced: the replacement rebuilds the tables with the given class.',
  },
  {
    input: 'toml.load(path_or_text_file)',
    old: 'accepts a path (str, bytes, PathLike) or a text file; a binary file raises TypeError',
    naive: 'tomli.load accepts only a binary file',
    handled:
      'Reproduced for paths and text files; the binary-file TypeError is kept. A list of paths is not supported.',
  },
  {
    input: 'datetime with an offset',
    old: 'tzinfo is toml.tz.TomlTz',
    naive: 'tzinfo is datetime.timezone',
    handled: 'Accepted: the instants are equal; the séance compares the UTC offset, not the class.',
  },
  {
    input: 'toml.loads(\'a = [","]\')',
    old: '{"a": ["", ""]} (an array string that starts with a comma is split into two empty strings)',
    naive: '{"a": [","]}',
    handled:
      'Accepted: tomli is right. The séance leaves such strings out of the generated documents (toml_reads_alike) and pins both answers in a separate test.',
  },
  {
    input: 'toml.loads(\'a = "\\\\""\')',
    old: '{"a": ""} (a string that is one quote, or starts with two quotes, is lost)',
    naive: '{"a": "\\""}',
    handled: 'Accepted: tomli is right. Left out of the generated documents and pinned, as above.',
  },
  {
    input: 'toml.loads(\'a = "\\\\u001f\\\\\\\\u"\')',
    old: 'raises TomlDecodeError (a string with a control character and a backslash followed by u is refused)',
    naive: '{"a": "\\u001f\\\\u"} (the string is read)',
    handled: 'Accepted: tomli is right. Left out of the generated documents and pinned, as above.',
  },
  {
    input: 'toml.loads("a .b = 1")',
    old: '{"a ": {"b": 1}} (the space before the dot of a dotted key becomes part of the key)',
    naive: '{"a": {"b": 1}}',
    handled:
      'Accepted: tomli is right. Only damaged documents can hold it; pinned in a separate test.',
  },
  {
    input: 'toml.loads("a = [-0.0]")',
    old: '{"a": [0.0]} (the sign of a negative zero is lost)',
    naive: '{"a": [-0.0]} (the sign is kept, as TOML says)',
    handled:
      'Accepted: tomli keeps the sign. The séance compares -0.0 as 0.0 and pins both answers in a separate test.',
  },
];

const REPLACEMENT = String.raw`"""Replacement for the toml package. Generated by Necromancer (recipe "toml").

Uses tomli (TOML 1.0, read only). Keeps the names and arguments of toml.loads and toml.load that
projects use: _dict, TomlDecodeError, a path or a text file for load.

Not covered: toml.dumps (use tomli-w), a list of paths for toml.load, and the decoder argument.
"""
import os

import tomli

TomlDecodeError = tomli.TOMLDecodeError


def _convert(value, factory):
    if factory is dict:
        return value
    if isinstance(value, dict):
        return factory((k, _convert(v, factory)) for k, v in value.items())
    if isinstance(value, list):
        return [_convert(v, factory) for v in value]
    return value


def loads(s, _dict=dict, decoder=None):
    if not isinstance(s, str):
        raise TypeError("Expecting something like a string")
    return _convert(tomli.loads(s), _dict)


def load(f, _dict=dict, decoder=None):
    if isinstance(f, (str, bytes, os.PathLike)):
        with open(f, encoding="utf-8") as handle:
            return loads(handle.read(), _dict)
    if hasattr(f, "read"):
        data = f.read()
        if not isinstance(data, str):
            raise TypeError("Expecting something like a string")
        return loads(data, _dict)
    raise TypeError("You can only load a file descriptor or a filename")
`;

const TEST = String.raw`"""Seance: toml -> tomli. Generated by Necromancer (recipe "toml").

Run: pytest seance/toml

Asks toml and the replacement the same generated questions and fails on any different answer.
Compared: the parsed value (tables as sorted key lists, datetimes by instant and offset, floats by
repr with a negative zero read as zero: toml loses its sign, tomli keeps it, see the pinned test) or,
when the call raises, the kind of error (any "...DecodeError" counts as one kind; the
message is never compared).

Valid documents must give equal values. Damaged documents and arbitrary text follow a looser rule:
where both parsers accept they must agree (except for the documented toml faults); where only one
accepts, the standard decides and the case is counted (see the Hypothesis statistics); where both
refuse the error kinds agree unless toml crashed. The replacement must also be transparent: it answers
exactly like tomli.loads.
"""
import datetime
import math
import os
import re
import tempfile
import warnings

import pytest
from hypothesis import HealthCheck, event, example, given, settings
from hypothesis import strategies as st

import toml as old
import tomli
from toml_replacement import TomlDecodeError, load, loads

warnings.simplefilter("ignore")
SLOW = dict(deadline=None, suppress_health_check=[HealthCheck.too_slow, HealthCheck.data_too_large])


# --- comparing answers -----------------------------------------------------------------------

def kind(exc):
    name = type(exc).__name__
    return "DecodeError" if name.lower().endswith("decodeerror") else name


def norm(value):
    if isinstance(value, dict):
        return ("table", sorted((k, norm(v)) for k, v in value.items()))
    if isinstance(value, list):
        return ("list", [norm(v) for v in value])
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, float):
        # "value + 0.0" turns -0.0 into 0.0: toml loses the sign of a negative zero and tomli keeps it,
        # a known difference (pinned in test_accepted_differences) that must not fail the comparison.
        return ("float", "nan" if math.isnan(value) else repr(value + 0.0))
    if isinstance(value, datetime.datetime):
        offset = value.utcoffset()
        return ("datetime", value.replace(tzinfo=None).isoformat(), None if offset is None else offset.total_seconds())
    if isinstance(value, (datetime.date, datetime.time)):
        return (type(value).__name__, value.isoformat())
    return (type(value).__name__, value)


def outcome(fn, *args, **kwargs):
    try:
        return ("ok", norm(fn(*args, **kwargs)))
    except Exception as exc:  # the kind of error is the answer
        return ("error", kind(exc))


# --- generating documents --------------------------------------------------------------------

def basic_string(s):
    out = '"'
    for ch in s:
        code = ord(ch)
        if ch == '"':
            out += '\\"'
        elif ch == "\\":
            out += "\\\\"
        elif code < 0x20 or code == 0x7F:
            out += "\\u%04x" % code
        else:
            out += ch
    return out + '"'


def render_key(k):
    return k if re.fullmatch(r"[A-Za-z0-9_-]+", k) else basic_string(k)


def render_value(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, str):
        return basic_string(v)
    if isinstance(v, (int, float)):
        return repr(v)
    if isinstance(v, (datetime.datetime, datetime.date, datetime.time)):
        return v.isoformat()
    if isinstance(v, list):
        return "[" + ", ".join(render_value(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{ " + ", ".join(render_key(k) + " = " + render_value(x) for k, x in v.items()) + " }"
    raise TypeError(v)


def render_table(d, path):
    lines = []
    subs = []
    for k, v in d.items():
        if isinstance(v, dict):
            subs.append((k, v))
        else:
            lines.append(render_key(k) + " = " + render_value(v))
    out = "\n".join(lines)
    for k, v in subs:
        p = path + [k]
        out += "\n[" + ".".join(render_key(x) for x in p) + "]\n" + render_table(v, p)
    return out


def toml_reads_alike(s):
    """toml mangles a few strings that tomli reads right. Found by trying every string of up to four
    characters from a set of awkward ones (quotes, commas, backslashes, brackets, spaces): toml loses a
    string that is one quote or starts with two, and splits or loses one that starts with a comma (after
    any spaces or tabs), and refuses one that holds a control character and also a backslash followed
    by u. They are left out of the generated documents and pinned, with both answers, in
    test_toml_bugs_that_tomli_fixes."""
    if s.lstrip(" \t").startswith((",", '""')) or s == '"' or s.endswith('",'):
        return False
    controls = any(ord(c) < 32 or ord(c) == 127 for c in s)
    return not (controls and ("\\u" in s or "\\U" in s))


text = st.text(alphabet=st.characters(blacklist_categories=("Cs",)), max_size=8).filter(toml_reads_alike)
# toml does not process escapes in quoted keys (it keeps the backslash), so keys that need an
# escape, with a colon or with a non-ASCII letter, are left out of the strict properties; they are pinned in test_toml_bugs_that_tomli_fixes.
plain_text = st.text(
    alphabet=st.characters(whitelist_categories=("L", "N")),
    min_size=1,
    max_size=8,
)
# Quoted keys are left to the pinned examples: toml mishandles them in several ways.
keys = st.from_regex(r"[A-Za-z0-9_-]{1,6}", fullmatch=True)
offsets = st.one_of(
    st.none(),
    st.integers(min_value=-12 * 60 + 1, max_value=14 * 60).map(lambda m: datetime.timezone(datetime.timedelta(minutes=m))),
)
datetimes = st.datetimes(min_value=datetime.datetime(1, 1, 1), timezones=st.none()).flatmap(
    lambda d: offsets.map(lambda tz: d.replace(tzinfo=tz))
)
scalars = st.one_of(
    text,
    st.integers(min_value=-(2**62), max_value=2**62),
    st.floats(allow_nan=False, allow_infinity=False),
    st.booleans(),
    datetimes,
    st.dates(min_value=datetime.date(1, 1, 1)),
    # toml drops the fraction of a time without a date (pinned below), so none is generated here.
    st.times().map(lambda t: t.replace(microsecond=0)),
)


def homogeneous(strategy):
    return st.lists(strategy, max_size=4)


leaf = st.one_of(
    scalars,
    homogeneous(text),
    homogeneous(st.integers(min_value=-(2**62), max_value=2**62)),
    homogeneous(st.booleans()),
    homogeneous(st.floats(allow_nan=False, allow_infinity=False)),
    homogeneous(st.dictionaries(keys, st.integers(min_value=-1000, max_value=1000), max_size=2)),
)
tables = st.recursive(
    st.dictionaries(keys, leaf, max_size=4),
    lambda inner: st.dictionaries(keys, st.one_of(leaf, inner), max_size=4),
    max_leaves=10,
)
documents = tables.map(lambda d: render_table(d, []))

DAMAGE = list("\"'[]{}=,.#\n \t01a\\")


@st.composite
def damaged(draw):
    doc = draw(documents)
    for _ in range(draw(st.integers(min_value=1, max_value=3))):
        if not doc:
            doc = draw(st.text(alphabet=DAMAGE, max_size=3))
            continue
        i = draw(st.integers(min_value=0, max_value=len(doc) - 1))
        op = draw(st.sampled_from(["delete", "insert", "replace"]))
        ch = draw(st.sampled_from(DAMAGE))
        doc = doc[:i] + (ch if op != "delete" else "") + (doc[i:] if op == "insert" else doc[i + 1:])
    return doc


# Documents that exercise the edges of the format; each is also a regression example below.
EDGE = [
    "a = 1", "a = 1\na = 2", "[a]\nb = 1\n[a]\nc=2", "a = 1_000", "a = 0x10", "a = 0o17", "a = 0b101",
    "a = +1", "a = 1.0e3", "a = inf", "a = -inf", "a = nan", "a = [1, \"a\"]", "a = [1,\n2,]",
    "a = {b = 1}", "a = 1979-05-27T07:32:00Z", "a = 1979-05-27 07:32:00", "a = 1979-05-27", "a = 07:32:00.5",
    "\"a b\" = 1", "a.b = 1", "[a.b]\nc=1", "a = \"\"\"x\ny\"\"\"", "a = '''x'''", "a = TRUE", "a = ",
    "a", "= 1", "a = \"\\u00e9\"", "a = \"\\x41\"", "[[t]]\na=1\n[[t]]\na=2", "a = 1\r\nb = 2",
    "a = 1e", "a = .5", "a = 5.", "a = 00", "a = \"\\q\"", "# c\na = 1 # d", "", "\n\n", "a = 'x\\n'",
    "[a]\n[a.b]\n[a]", "a = 1\n[a]", "[a]\nb = 1\n[a.b]", "a = [[1], [\"x\"]]", "a = [{b = 1}, {c = 2}]",
    "a = \"tab\there\"", "a = \"nul\\u0000\"", "key = \"\\U0001F600\"", "a=1 b=2", "a = 1 # \x00",
]


# --- toml's own faults: documents where toml is lenient or wrong, found by this seance ----------------
#
# Each pattern is a documented difference, not a gap in the checks: tomli follows the TOML 1.0 rules
# and toml does not. test_toml_bugs_that_tomli_fixes pins one example of each on both sides.

CONTROL_CHARACTER = re.compile(r"[\x00-\x08\x0b-\x1f\x7f]")
TWO_ASSIGNMENTS_ON_A_LINE = re.compile(r"=[^#\n]*[^\s#\n,=\[{][ \t]+[A-Za-z0-9_-]+[ \t]*=")
QUOTED_KEY_WITH_BACKSLASH = re.compile(r'"[^"\n]*\\[^"\n]*"[ \t]*(=|\.|\])')
TIME_WITH_FRACTION = re.compile(r"(=|\[|,)[ \t]*\d\d:\d\d:\d\d\.\d")


def toml_is_lenient(doc):
    """True when toml accepts a document that TOML 1.0 forbids."""
    return bool(CONTROL_CHARACTER.search(doc) or TWO_ASSIGNMENTS_ON_A_LINE.search(doc))


STRING_LITERAL = re.compile(r'"((?:[^"\\\n]|\\.)*)"')
COMMA_FIRST = re.compile(r'[\[,=]\s*"[ \t]*,')  # a string that starts with a comma
QUOTE_FIRST = re.compile(r'[\[,=]\s*"\\"(?:\\"|")')  # a string that is a quote, or starts with two
SPACE_BEFORE_DOT_IN_KEY = re.compile(r'(?:^|[{,])[ \t]*[A-Za-z0-9_-]+[ \t]+\.', re.MULTILINE)
CONTROL_ESCAPE = re.compile(r'\\u00(?:[01][0-9a-fA-F]|7[fF])')
BACKSLASH_U = re.compile(r'\\\\[uU]')


def toml_misreads_a_string(doc):
    """The string faults of toml that toml_reads_alike keeps out of the generated documents, for
    documents that were damaged afterwards: toml splits or loses a string that starts with a comma or
    with a quote, and refuses a string that holds a control character and a backslash followed by u."""
    if COMMA_FIRST.search(doc) or QUOTE_FIRST.search(doc):
        return True
    return any(
        CONTROL_ESCAPE.search(m.group(1)) and BACKSLASH_U.search(m.group(1))
        for m in STRING_LITERAL.finditer(doc)
    )


def toml_is_wrong(doc):
    """True when toml accepts the document but reads part of it wrongly."""
    return bool(
        QUOTED_KEY_WITH_BACKSLASH.search(doc)
        or TIME_WITH_FRACTION.search(doc)
        or SPACE_BEFORE_DOT_IN_KEY.search(doc)
        or toml_misreads_a_string(doc)
    )


def check_one_sided(doc):
    """The rule for documents that may be damaged. Returns what happened, for the statistics."""
    o = outcome(old.loads, doc)
    n = outcome(loads, doc)
    if o[0] == "ok" and n[0] == "ok":
        assert n == o or toml_is_wrong(doc), "different values: %r" % (doc,)
        return "same" if n == o else "toml reads it wrongly"
    if o[0] == "ok":
        return "toml accepts what TOML 1.0 forbids"  # tomli refuses: stricter, by the standard
    if n[0] == "ok":
        return "tomli accepts what toml refuses"  # more permissive, by the standard
    if o != n:
        # Both refuse. The kinds must agree unless toml crashed instead of refusing.
        assert o[1] not in ("DecodeError", "TypeError"), "different errors: %r %r" % (o, n)
        return "toml crashes"
    return "both refuse"


# --- the properties --------------------------------------------------------------------------

@settings(max_examples=400, **SLOW)
@given(documents)
def test_valid_documents_parse_to_the_same_value(doc):
    assert outcome(loads, doc) == outcome(old.loads, doc)


@settings(max_examples=600, **SLOW)
@given(damaged())
def test_damaged_documents_agree_wherever_both_parsers_accept(doc):
    event(check_one_sided(doc))


@settings(max_examples=400, **SLOW)
@given(st.one_of(documents, damaged(), st.text(max_size=40)))
def test_the_replacement_is_transparent_for_any_text(doc):
    # the replacement adds nothing to tomli.loads except the old names and the _dict argument
    assert outcome(loads, doc) == outcome(tomli.loads, doc)


@settings(max_examples=400, **SLOW)
@given(st.text(max_size=40))
def test_arbitrary_text_agrees_wherever_both_parsers_accept(doc):
    event(check_one_sided(doc))


@pytest.mark.parametrize("doc", EDGE)
def test_edge_documents(doc):
    check_one_sided(doc)


def test_errors_are_the_same_kind_when_both_refuse():
    for doc in ["a = ", "a", "= 1", "a = 1\na = 2", "a = \"\\q\"", "a = 00"]:
        assert outcome(old.loads, doc) == ("error", "DecodeError")
        assert outcome(loads, doc) == ("error", "DecodeError")


def test_the_old_exception_name_still_catches_errors():
    with pytest.raises(TomlDecodeError):
        loads("a = ")
    assert TomlDecodeError is tomli.TOMLDecodeError
    assert issubclass(TomlDecodeError, ValueError) and issubclass(old.TomlDecodeError, ValueError)


@settings(max_examples=60, **SLOW)
@given(documents)
def test_load_from_a_path_a_text_file_and_a_binary_file(doc):
    with tempfile.TemporaryDirectory() as folder:
        path = os.path.join(folder, "x.toml")
        with open(path, "w", encoding="utf-8", newline="") as handle:
            handle.write(doc)
        assert outcome(load, path) == outcome(old.load, path)
        assert outcome(load, os.fsencode(path)) == outcome(old.load, os.fsencode(path))
        with open(path, encoding="utf-8", newline="") as a, open(path, encoding="utf-8", newline="") as b:
            assert outcome(load, a) == outcome(old.load, b)
        with open(path, "rb") as a, open(path, "rb") as b:
            assert outcome(load, a) == outcome(old.load, b) == ("error", "TypeError")


def test_load_with_bad_arguments_fails_alike():
    for bad in [None, 1, 2.5]:
        assert outcome(load, bad) == outcome(old.load, bad) == ("error", "TypeError")
    assert outcome(load, "/no/such/file.toml") == outcome(old.load, "/no/such/file.toml")


def test_loads_with_non_text_fails_alike():
    for bad in [None, 1, b"a = 1", ["a = 1"]]:
        assert outcome(loads, bad) == outcome(old.loads, bad) == ("error", "TypeError")


def test_the_dict_argument_builds_the_requested_tables():
    import collections
    doc = "a = 1\n[b]\nc = 2\n[[d]]\ne = 3"
    new = loads(doc, _dict=collections.OrderedDict)
    assert type(new) is collections.OrderedDict and type(new["b"]) is collections.OrderedDict
    assert type(new["d"][0]) is collections.OrderedDict
    assert norm(new) == norm(old.loads(doc, _dict=collections.OrderedDict))


# --- known differences, pinned on both sides: if either changes, review the migration -------------

def test_accepted_differences():
    assert outcome(old.loads, 'a = [1, "x"]') == ("error", "DecodeError")
    assert outcome(loads, 'a = [1, "x"]') == ("ok", ("table", [("a", ("list", [("int", 1), ("str", "x")]))]))
    assert outcome(old.loads, 'a = "\\x41"') == ("error", "DecodeError")
    assert outcome(loads, 'a = "\\x41"') == ("ok", ("table", [("a", ("str", "A"))]))
    # A negative zero: toml answers 0.0, tomli -0.0. norm() reads both as 0.0; here the sign is checked.
    for doc, get in [("a = -0.0", lambda t: t["a"]), ("0 = [-0.0]", lambda t: t["0"][0]), ("a = {b = -0.0}", lambda t: t["a"]["b"])]:
        assert math.copysign(1.0, get(old.loads(doc))) == 1.0
        assert math.copysign(1.0, get(loads(doc))) == -1.0
        assert norm(old.loads(doc)) == norm(loads(doc))


def test_toml_bugs_that_tomli_fixes():
    # toml keeps the backslash of an escape inside a quoted key
    assert old.loads('"\\u0041" = 1') == {"\\u0041": 1}
    assert loads('"\\u0041" = 1') == {"A": 1}
    # toml drops the fraction of a time
    assert old.loads("a = 07:32:00.5")["a"] == datetime.time(7, 32)
    assert loads("a = 07:32:00.5")["a"] == datetime.time(7, 32, 0, 500000)
    # toml accepts two assignments on one line, and control characters in comments and strings
    assert old.loads("a=1 b=2") == {"a=1 b": 2}
    assert outcome(loads, "a=1 b=2") == ("error", "DecodeError")
    assert old.loads("a = 1 # \x00") == {"a": 1}
    assert outcome(loads, "a = 1 # \x00") == ("error", "DecodeError")
    assert old.loads('a = "x\x7f"') == {"a": "x\x7f"}
    assert outcome(loads, 'a = "x\x7f"') == ("error", "DecodeError")
    # toml silently loses everything after some quoted keys (a colon, a non-ASCII letter)
    assert old.loads('"\u00aa" = ""\n0 = ""') == {}
    assert loads('"\u00aa" = ""\n0 = ""') == {"\u00aa": "", "0": ""}
    assert old.loads('":" = ""\n0 = ""') == {}
    assert loads('":" = ""\n0 = ""') == {":": "", "0": ""}
    # toml crashes with an internal error on this document, and refuses an empty table name
    assert outcome(old.loads, '"" = ""\n0 = ""') == ("error", "UnboundLocalError")
    assert outcome(loads, '"" = ""\n0 = ""') == ("ok", ("table", [("", ("str", "")), ("0", ("str", ""))]))
    assert outcome(old.loads, '[""]') == ("error", "DecodeError")
    assert outcome(loads, '[""]') == ("ok", ("table", [("", ("table", []))]))
    # toml splits an array string that starts with a comma, and loses a string made of a quote
    assert old.loads('a = [","]') == {"a": ["", ""]}
    assert loads('a = [","]') == {"a": [","]}
    assert old.loads('a = ["a", ","]') == {"a": ["a", "", ""]}
    assert loads('a = ["a", ","]') == {"a": ["a", ","]}
    assert old.loads('a = "\\""') == {"a": ""}
    assert loads('a = "\\""') == {"a": '"'}
    assert old.loads('a = "\\"\\""') == {"a": ""}
    assert loads('a = "\\"\\""') == {"a": '""'}
    # toml keeps the space before the dot of a dotted key as part of the key
    assert old.loads("a .b = 1") == {"a ": {"b": 1}}
    assert loads("a .b = 1") == {"a": {"b": 1}}
    # toml refuses a string that holds a control character and a backslash followed by u
    assert outcome(old.loads, 'a = "\\u001f\\\\u"') == ("error", "DecodeError")
    assert outcome(loads, 'a = "\\u001f\\\\u"') == ("ok", ("table", [("a", ("str", "\x1f\\u"))]))
    # toml accepts an unfinished array
    assert old.loads("a = [true[") == {"a": [True]}
    assert outcome(loads, "a = [true[") == ("error", "DecodeError")


def test_the_naive_call_is_not_a_drop_in():
    import collections
    with pytest.raises(TypeError):
        tomli.loads("a = 1", _dict=collections.OrderedDict)
    with pytest.raises(AttributeError):
        tomli.load("some/path.toml")  # tomli.load needs a binary file object, not a path
    assert not hasattr(tomli, "TomlDecodeError")


# --- calls this project makes today, from the usage scan (empty when none was given) --------------

__PROJECT_LOADS__


@pytest.mark.parametrize("args", PROJECT_CALLS)
def test_the_replacement_answers_like_toml_on_the_calls_this_project_makes(args):
    assert outcome(loads, *args) == outcome(old.loads, *args)
`;

function build(ctx: RecipeContext): SeanceBundle {
  const pick = (m: string): boolean => m === 'loads';
  const files: SeanceFile[] = [
    {
      path: `${DIR}/test_seance_toml.py`,
      content: TEST.replace('__PROJECT_LOADS__', () => pyProjectCalls(ctx.usage, pick)),
      role: 'test',
    },
    { path: `${DIR}/toml_replacement.py`, content: REPLACEMENT, role: 'replacement' },
  ];
  const compares = [
    'The parsed value: tables as sorted keys, lists in order, floats by repr (a negative zero as zero: toml loses its sign, tomli keeps it), datetimes by local time and UTC offset (not by tzinfo class). Or, when the call raises, the kind of error: any "...DecodeError" is one kind, the message is never compared.',
    'Valid documents are generated from a model (nested tables, inline tables, arrays, strings with unicode and escapes, integers, floats, booleans, dates, times, datetimes with offsets) and must give equal values.',
    'Damaged documents (random edits) and arbitrary text: where both accept they agree (apart from the documented faults of toml); where only one accepts, TOML 1.0 decides and the case is counted; where both refuse the error kinds agree unless toml crashed. The replacement must answer exactly like tomli.loads.',
    'load: a path (str, bytes), a text file and a binary file; bad arguments. loads: non-text arguments, the _dict argument.',
    'Not covered: toml.dumps (use tomli-w), a list of paths for toml.load, the decoder argument.',
    callsNote(ctx.usage, pick),
  ];
  const install = ['pip install pytest hypothesis tomli'];
  const oldVersions = oldVersionsFor('toml', depOfContext(ctx));
  compares.push(`Versions: ${oldVersions.note}`);
  const run = 'pytest seance/toml';
  files.push({
    path: `${DIR}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: 'toml to tomli',
      recipe: 'toml',
      files: [
        {
          path: `${DIR}/test_seance_toml.py`,
          what: 'the differential property test (pytest and Hypothesis)',
        },
        {
          path: `${DIR}/toml_replacement.py`,
          what: 'loads and load on top of tomli, with the old names and arguments',
        },
      ],
      install,
      run,
      compares,
      known: TOML_KNOWN,
      versions: oldVersions.note,
      notes: [
        'On Python 3.11 or later use tomllib from the standard library instead of tomli; the API is the same.',
      ],
    }),
  });
  return makeBundle({
    language: 'python',
    recipe: 'toml',
    title: 'toml to tomli',
    files,
    install,
    run,
    compares,
    knownDifferences: TOML_KNOWN,
    members: ['loads', 'load', 'TomlDecodeError'],
    oldVersions,
  });
}

function mutants(): Mutant[] {
  const path = `${DIR}/toml_replacement.py`;
  return [
    {
      id: 'naive-tomli',
      description: 'tomli.loads and tomli.load used directly (the obvious migration)',
      files: [
        {
          path,
          role: 'replacement',
          content: [
            'import tomli',
            'TomlDecodeError = tomli.TOMLDecodeError',
            'loads = tomli.loads',
            'load = tomli.load',
            '',
          ].join('\n'),
        },
      ],
    },
    {
      id: 'swallows-errors',
      description: 'returns an empty table when the document is invalid',
      files: [
        {
          path,
          role: 'replacement',
          content: REPLACEMENT.replace(
            '    return _convert(tomli.loads(s), _dict)',
            '    try:\n        return _convert(tomli.loads(s), _dict)\n    except tomli.TOMLDecodeError:\n        return {}',
          ),
        },
      ],
    },
  ];
}

